cat > fxclone/data.py <<'PY'
"""Data model, relaxed streaming JSON reader, and display formatting."""
import json
import math
import re

class Undefined:
    def __repr__(self): return 'undefined'
UNDEFINED = Undefined()
class Skip:
    pass
SKIP = Skip()

class RawNumber:
    def __init__(self, text): self.text = text
    def value(self):
        if 'nan' in self.text.lower(): return float('nan')
        if 'inf' in self.text.lower(): return -float('inf') if self.text.startswith('-') else float('inf')
        try: return int(self.text)
        except ValueError:
            try: return float(self.text)
            except ValueError: return float('nan')
class RawString(str):
    def __new__(cls, value, raw=None):
        obj = str.__new__(cls, value)
        obj.raw = raw
        return obj
class RawObject:
    def __init__(self, pairs=()): self.pairs = list(pairs)
class ForcedArray(list):
    """Slurping has its own multiline outer container."""
    pass


def numeric_key(key):
    return isinstance(key, str) and bool(re.fullmatch(r'0|[1-9][0-9]*', key)) and len(key) < 11 and int(key) < 4294967295

def ordered_keys(obj):
    keys = list(obj.keys())
    return sorted((k for k in keys if numeric_key(k)), key=int) + [k for k in keys if not numeric_key(k)]

def materialize(value):
    if isinstance(value, RawNumber): return value.value()
    if isinstance(value, RawString): return str(value)
    if isinstance(value, RawObject):
        d = {}
        for k, v in value.pairs: d[str(k)] = materialize(v)
        return {k: d[k] for k in ordered_keys(d)}
    if isinstance(value, list): return [materialize(v) for v in value]
    if isinstance(value, dict): return {str(k): materialize(v) for k,v in value.items()}
    return value


def numstr(x):
    if isinstance(x, RawNumber): return x.text
    if isinstance(x, int): return str(x)
    if math.isnan(x): return 'NaN'
    if math.isinf(x): return '-Infinity' if x < 0 else 'Infinity'
    if x == 0: return '0'
    s = repr(x)
    if 1e-6 <= abs(x) < 1e21:
        if x.is_integer(): return str(int(x))
        if 'e' in s:
            s = format(x, '.15f').rstrip('0').rstrip('.')
    elif 'e' in s:
        mant, exp = s.split('e')
        mant = mant.removesuffix('.0')
        n = int(exp)
        return mant + 'e' + ('+' if n >= 0 else '-') + str(abs(n))
    return s.removesuffix('.0')

def quote(s, preserve=True):
    if preserve and isinstance(s, RawString) and s.raw is not None: return s.raw
    return json.dumps(str(s), ensure_ascii=False, separators=(',', ':'))

def scalar(v, preserve=True):
    if isinstance(v, RawNumber): return v.text
    if v is None or v is UNDEFINED: return 'null'
    if v is True: return 'true'
    if v is False: return 'false'
    if isinstance(v, (int, float)): return numstr(v)
    if isinstance(v, str): return quote(v, preserve)
    return 'null'

def pairs(v):
    if isinstance(v, RawObject): return v.pairs
    if isinstance(v, dict): return [(k, v[k]) for k in ordered_keys(v)]
    return None

def is_number(v):
    return (isinstance(v, RawNumber) and bool(re.match(r'-?\d', v.text))) or (type(v) in (int,float) and math.isfinite(v))

def simple_object(v):
    p = pairs(v)
    if p is None or len(p) > 3: return False
    for k, val in p:
        if isinstance(val, (RawObject,dict,list)): return False
        if isinstance(val,str) and len(val.encode('utf-8', 'surrogatepass')) > 80: return False
    # Inlining uses the combined key and scalar widths.
    return sum(len(str(k).encode('utf-8')) + len(scalar(val).encode('utf-8','surrogatepass')) for k,val in p) <= 80

def display(v, no_inline=False, level=0, inline=False, root=True):
    p = pairs(v)
    pad = '  '*level
    if p is not None:
        if not p: return '{}'
        if inline and not no_inline:
            return '{ ' + ', '.join(quote(k)+': '+scalar(val) for k,val in p) + ' }'
        return '{\n' + ',\n'.join(pad+'  '+quote(k)+': '+display(val,no_inline,level+1,not no_inline and isinstance(val,list) and len(val)>0 and all(is_number(e) for e in val),False) for k,val in p)+'\n'+pad+'}'
    if isinstance(v,list):
        if not v: return '[\n]' if isinstance(v,ForcedArray) else '[]'
        if inline and not no_inline and all(is_number(e) for e in v): return '[ '+', '.join(scalar(e) for e in v)+' ]'
        child_inline = not no_inline and not isinstance(v,ForcedArray) and (all(simple_object(e) for e in v) or all(isinstance(e,list) and all(is_number(a) for a in e) for e in v))
        return '[\n'+',\n'.join(pad+'  '+display(e,no_inline,level+1,child_inline,False) for e in v)+'\n'+pad+']'
    if isinstance(v,str) and root: return str(v)
    if isinstance(v,RawNumber): return v.text
    return scalar(v)

def stringify_json(v, indent=None, sort=False):
    """ECMAScript JSON.stringify, not the terminal's relaxed formatter."""
    def clean(val, in_array=False):
        if isinstance(val,RawNumber): val=val.value()
        if isinstance(val,RawObject): val=materialize(val)
        if val is UNDEFINED or val is SKIP or callable(val): return None
        if isinstance(val,float) and not math.isfinite(val): return None
        if isinstance(val,list): return [clean(e,True) for e in val]
        if isinstance(val,dict): return {k:clean(val[k]) for k in ordered_keys(val) if val[k] is not UNDEFINED and val[k] is not SKIP and not callable(val[k])}
        return val
    if v is UNDEFINED or v is SKIP or callable(v): return UNDEFINED
    value = clean(v)
    # Use our numeric rendering, with configurable JSON whitespace.
    gap = ''
    if isinstance(indent,(int,float)): gap=' '*max(0,min(int(indent),10))
    elif isinstance(indent,str): gap=indent[:10]
    def rec(x,d):
