def play():
    try:
        width,height=os.get_terminal_size(sys.stdout.fileno())
    except OSError:
        width,height=80,24
    width=max(1,width);height=max(1,height)*2
    alive={(x,y) for y in range(height) for x in range(width) if random.random()<.25}
    stopped=False
