            sys.stdout.write('\x1b[H'+'\n'.join(rows));sys.stdout.flush()
            time.sleep(.05)
    finally:
        sys.stdout.write('\x1b[?25h\n');sys.stdout.flush();signal.signal(signal.SIGINT,old)
    raise SystemExit(2)
